import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';
import { BASE_URL } from './config';
import { showSnackbar } from './redux/slices/app';

class WebSocketService {
  constructor() {
    this.stompClient = null;
    this.connected = false;
    this.subscriptions = [];
    this.messageQueue = []; // Queue for messages to send after reconnect
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5; // Limit number of reconnection attempts
    this.isLoggedIn = false;
  }

  async connect({ token, dispatch }) {
    if (this.connected) return;

    dispatch((dispatch, getState) => {
      const { auth } = getState();
      this.isLoggedIn = auth.isLoggedIn;
    });

    // Ensure that stompClient is reset
    this.stompClient = null;

    const socket = new SockJS(`${BASE_URL}/ws`);
    this.stompClient = new Client({
      webSocketFactory: () => socket,
      connectHeaders: {
        Authorization: `Bearer ${token}`,
      },
      debug: (str) => {
        // console.log(str); // Debugging connection steps
      },
      reconnectDelay: 3000, // Wait 3 seconds before reconnecting
      heartbeatIncoming: 20000,
      heartbeatOutgoing: 10000,
    });

    this.stompClient.onConnect = () => {
      // console.log('WebSocket connected');
      this.connected = true;
      this.reconnectAttempts = 0; // Reset reconnect attempts

      // Resubscribe to previously subscribed topics
      this.subscriptions.forEach(({ topic, callback }) => {
        // console.log(`Resubscribing to topic: ${topic}`);
        this.subscribe(topic, callback);
      });

      // Send queued messages after reconnecting
      while (this.messageQueue.length > 0) {
        const { destination, body } = this.messageQueue.shift();
        this.sendMessage(destination, body);
      }
    };

    this.stompClient.onStompError = (error) => {
      // console.log('STOMP error:', error);
      this.connected = false;
      this.tryReconnect(token, dispatch);
    };

    this.stompClient.onWebSocketClose = () => {
      // console.log('WebSocket closed. Trying to reconnect...');
      this.connected = false;
      if (this.isLoggedIn) {
        this.tryReconnect(token, dispatch);
      }
    };

    this.stompClient.onWebSocketError = (error) => {
      // console.log('WebSocket error:', error);
      this.connected = false;
      this.tryReconnect(token, dispatch);
    };

    this.stompClient.activate();
    return this.stompClient;
  }

  tryReconnect(token, dispatch) {
    if (this.reconnectAttempts < this.maxReconnectAttempts) {
      setTimeout(() => {
        this.reconnectAttempts++;
        // console.log(`Reconnection attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts}`);
        dispatch(showSnackbar({ severity: "info", message: "Trying to Reconnect..." }));
        this.connect({ token, dispatch });
      }, 3000); // Delay before reconnect attempt
    } else {
      dispatch(showSnackbar({ severity: "error", message: "Failed to Reconnect. Please refresh your browser." }));
    }
  }

  disconnect() {
    if (this.stompClient && this.connected) {
      // console.log('Disconnecting WebSocket');
      this.stompClient.deactivate();
      this.connected = false;
      this.subscriptions = []; // Clear subscriptions when disconnected
      this.unsubscribe();
    }
  }

  sendMessage(destination, body) {
    if (this.stompClient && this.connected) {
      // console.log(`Sending message to ${destination}`);
      this.stompClient.publish({ destination, body });
    } else {
      // console.log('Connection lost, queuing message');
      this.messageQueue.push({ destination, body }); // Queue messages
    }
  }

  subscribe(topic, callback) {
    if (this.stompClient && this.connected) {
      // console.log(`Subscribing to topic: ${topic}`);
      const subs = this.stompClient.subscribe(topic, (message) => {
        callback(message.body);
      });

      // Store subscription details if not already stored
      const existingSub = this.subscriptions.find((sub) => sub.topic === topic);
      if (!existingSub) {
        this.subscriptions.push({ topic, callback });
      }

      return subs;
    }
  }

  unsubscribe() {
    this.subscriptions.forEach((element) => {
      element.unsubscribe();
    });

    // console.log('Unsubscribed from all topics');
    // Clear subscriptions list after unsubscribing
    this.subscriptions = [];
  }
}

const webSocketService = new WebSocketService();
export default webSocketService;
